PAGES = {
 "a-propos": {
  "fr": ("À propos", "<p>Bienvenue à la <strong>Data Librairie digitale</strong> ! Nous accompagnons les élèves, les parents, les écoles et les entreprises avec un large choix de fournitures scolaires et de bureau, de livres et de matériel de beaux-arts.</p><p>Nous sommes aussi votre <strong>espace de services digitaux</strong> : démarches administratives en ligne, rédaction de CV et de lettres, impression, scan et mise en page de vos documents.</p><h2>Nos engagements</h2><ul><li>Des marques de qualité au meilleur prix</li><li>Les listes scolaires préparées pour vous</li><li>Livraison partout au Maroc, paiement à la livraison</li><li>Un conseil personnalisé en magasin et sur WhatsApp</li></ul>"),
  "en": ("About us", "<p>Welcome to the <strong>Data Digital Bookshop</strong>! We support pupils, parents, schools and companies with a wide range of school and office supplies, books and fine-arts materials.</p><p>We are also your <strong>digital services point</strong>: online administrative procedures, CV and letter writing, printing, scanning and document layout.</p><h2>Our commitments</h2><ul><li>Quality brands at the best price</li><li>School lists prepared for you</li><li>Delivery all over Morocco, cash on delivery</li><li>Personal advice in store and on WhatsApp</li></ul>"),
  "ar": ("من نحن", "<p>مرحباً بكم في <strong>Data المكتبة الرقمية</strong>! نرافق التلاميذ والآباء والمدارس والمقاولات بتشكيلة واسعة من اللوازم المدرسية والمكتبية والكتب وأدوات الفنون.</p><p>نحن أيضاً <strong>فضاؤكم للخدمات الرقمية</strong>: الإجراءات الإدارية عبر الإنترنت، تحرير السير الذاتية والرسائل، الطباعة والمسح الضوئي وتنسيق الوثائق.</p><h2>التزاماتنا</h2><ul><li>علامات ذات جودة بأفضل الأسعار</li><li>تحضير اللوائح المدرسية</li><li>التوصيل إلى جميع أنحاء المغرب والدفع عند الاستلام</li><li>نصيحة شخصية في المتجر وعبر واتساب</li></ul>"),
 },
 "livraison-retours": {
  "fr": ("Livraison et retours", "<h2>Livraison</h2><ul><li>Livraison partout au Maroc en 24 à 72 h selon la ville.</li><li>Frais de livraison : 30 Dhs. Livraison gratuite dès 300 Dhs d’achat.</li><li>Retrait gratuit en magasin.</li></ul><h2>Paiement</h2><p>Vous payez en espèces à la réception de votre commande.</p><h2>Retours</h2><p>Un article ne vous convient pas ? Vous disposez de 7 jours après réception pour nous le retourner, dans son emballage d’origine et non utilisé. Contactez-nous avant tout retour.</p>"),
  "en": ("Delivery & returns", "<h2>Delivery</h2><ul><li>Delivery all over Morocco within 24 to 72 hours depending on the city.</li><li>Delivery fee: 30 Dhs. Free delivery from 300 Dhs.</li><li>Free in-store pickup.</li></ul><h2>Payment</h2><p>You pay in cash when you receive your order.</p><h2>Returns</h2><p>Not happy with an item? You have 7 days after delivery to return it, unused and in its original packaging. Please contact us first.</p>"),
  "ar": ("التوصيل والإرجاع", "<h2>التوصيل</h2><ul><li>التوصيل إلى جميع مدن المغرب خلال 24 إلى 72 ساعة حسب المدينة.</li><li>مصاريف التوصيل: 30 درهماً. التوصيل مجاني ابتداءً من 300 درهم.</li><li>الاستلام مجاني من المتجر.</li></ul><h2>الأداء</h2><p>تدفع نقداً عند استلام طلبيتك.</p><h2>الإرجاع</h2><p>لم يناسبك منتج؟ لديك 7 أيام بعد الاستلام لإرجاعه غير مستعمل وفي غلافه الأصلي. تواصل معنا قبل أي إرجاع.</p>"),
 },
 "conditions-generales-de-vente": {
  "fr": ("Conditions générales de vente", "<p><em>Modèle à compléter et à faire vérifier avant la mise en ligne.</em></p><h2>1. Objet</h2><p>Les présentes conditions régissent les ventes et prestations de services réalisées par [nom de la société], [adresse], RC [numéro], ICE [numéro].</p><h2>2. Prix</h2><p>Les prix sont indiqués en dirhams marocains (MAD), toutes taxes comprises, hors frais de livraison. Les frais officiels des administrations ne sont pas inclus dans les prix des services.</p><h2>3. Commande</h2><p>Le client ajoute les produits à son panier puis remplit le bon de commande (coordonnées, mode de livraison, mode de paiement). La validation du bon de commande vaut acceptation des présentes conditions. La commande est ensuite confirmée par WhatsApp ou par téléphone, avec les frais de livraison. En cas d’erreur, le client peut demander l’annulation dans les 24 h. En cas d’indisponibilité d’un produit, le client en est informé et peut annuler ou modifier sa commande.</p><h2>4. Paiement</h2><p>Pour régler sa commande, le client choisit le moyen de paiement parmi ceux proposés sur le bon de commande : paiement à la livraison (espèces), virement bancaire, paiement en magasin lors du retrait et, lorsqu’il est activé, paiement par carte bancaire. Les paiements par carte sont sécurisés par le Centre Monétique Interbancaire (CMI) ; les données bancaires ne sont jamais transmises à la librairie. En cas de virement, la commande est préparée dès réception des fonds.</p><h2>5. Livraison</h2><p>Les produits sont livrés à l’adresse indiquée sur le bon de commande, partout au Maroc, ou retirés gratuitement en magasin. Les frais de livraison dépendent de la ville et sont communiqués avant l’envoi. Le client vérifie la marchandise à la réception et signale tout dommage dans un délai d’un jour.</p><h2>6. Services administratifs</h2><p>Nous agissons comme intermédiaire et ne pouvons garantir la décision de l’administration. Les documents transmis sont utilisés uniquement pour la démarche demandée.</p>"),
  "en": ("Terms of sale", "<p><em>Template to complete and have checked before publishing.</em></p><h2>1. Purpose</h2><p>These terms govern the sales and services provided by [company name], [address], RC [number], ICE [number].</p><h2>2. Prices</h2><p>Prices are in Moroccan dirhams (MAD), all taxes included, excluding delivery. Official administration fees are not included in service prices.</p><h2>3. Orders</h2><p>The customer adds products to the cart and fills in the order form (details, delivery method, payment method). Submitting the order form means accepting these terms. The order is then confirmed on WhatsApp or by phone, together with the delivery fee. In case of a mistake, the customer may request cancellation within 24 hours. If a product is unavailable, the customer is informed and may cancel or change the order.</p><h2>4. Payment</h2><p>The customer chooses a payment method from those offered on the order form: cash on delivery, bank transfer, payment in store at pickup and, when enabled, bank card. Card payments are secured by the Centre Monétique Interbancaire (CMI); card details are never shared with the shop. For bank transfers, the order is prepared once the funds are received.</p><h2>5. Delivery</h2><p>Products are delivered to the address given on the order form, anywhere in Morocco, or picked up free of charge in store. Delivery fees depend on the city and are communicated before shipping. The customer checks the goods on receipt and reports any damage within one day.</p><h2>6. Administrative services</h2><p>We act as an intermediary and cannot guarantee the administration’s decision. Documents you send are used only for the requested procedure.</p>"),
  "ar": ("الشروط العامة للبيع", "<p><em>نموذج يجب إتمامه والتحقق منه قبل النشر.</em></p><h2>1. الموضوع</h2><p>تنظم هذه الشروط عمليات البيع والخدمات التي تقدمها [اسم الشركة]، [العنوان]، السجل التجاري [رقم]، ICE [رقم].</p><h2>2. الأسعار</h2><p>الأسعار بالدرهم المغربي شاملة للضرائب وبدون مصاريف التوصيل. الرسوم الرسمية للإدارات غير مشمولة في أسعار الخدمات.</p><h2>3. الطلب</h2><p>يضيف الزبون المنتجات إلى السلة ثم يملأ ورقة الطلب (المعلومات، طريقة التوصيل، طريقة الأداء). يُعدّ تأكيد ورقة الطلب قبولاً لهذه الشروط. يتم بعد ذلك تأكيد الطلب عبر واتساب أو الهاتف مع مصاريف التوصيل. في حالة الخطأ، يمكن للزبون طلب الإلغاء خلال 24 ساعة. وفي حالة عدم توفر منتج، يتم إخباره ويمكنه إلغاء الطلب أو تعديله.</p><h2>4. الأداء</h2><p>يختار الزبون طريقة الأداء من بين الطرق المقترحة في ورقة الطلب: الدفع عند الاستلام نقداً، التحويل البنكي، الأداء في المتجر عند الاستلام، وعند تفعيله الأداء بالبطاقة البنكية. عمليات الأداء بالبطاقة مؤمَّنة من طرف المركز النقدي البيبنكي (CMI)، ولا تُرسل معلومات البطاقة إلى المكتبة أبداً. في حالة التحويل، يُجهَّز الطلب فور التوصل بالمبلغ.</p><h2>5. التوصيل</h2><p>تُسلَّم المنتجات إلى العنوان المذكور في ورقة الطلب في جميع أنحاء المغرب، أو تُستلم مجاناً من المتجر. تختلف مصاريف التوصيل حسب المدينة ويتم إبلاغ الزبون بها قبل الإرسال. يتحقق الزبون من السلعة عند الاستلام ويبلغ عن أي ضرر داخل أجل يوم واحد.</p><h2>6. الخدمات الإدارية</h2><p>نعمل كوسيط ولا يمكننا ضمان قرار الإدارة. تُستعمل الوثائق المرسلة فقط للإجراء المطلوب.</p>"),
 },
}

